(() => {
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const regions=[
 ['Whispering Woods','🌲','Mossling','Thornfang','Elder Treant'],['Ashen Highlands','🌋','Cinder Wisp','Ember Hound','Pyre Drake'],['Frostfall Reach','❄','Snow Wraith','Ice Troll','Glacier Titan'],['Sunken Kingdom','🌊','Drowned Guard','Tide Siren','Abyssal King'],['Eclipse Desert','☀','Dune Stalker','Sand Djinn','Sphinx of Dusk'],['Astral Spire','🌌','Voidling','Star Knight','Astral Seraph'],['Wyrmfire Peaks','🐉','Drakelet','Flame Basilisk','Ancient Wyrm'],['Hollow Cathedral','⛪','Fallen Acolyte','Doom Priest','Hollow Saint'],['Demon Realm','🔥','Hellspawn','Dread Fiend','Demon Sovereign'],['Eternal Citadel','🏰','Aether Warden','Celestial Knight','Eternal Dragon']
];
const rarity=['Common','Rare','Epic','Legendary','Mythic','Divine','Eternal'];
const gearTypes=[['Weapon','⚔'],['Armor','▣'],['Helmet','◈'],['Gloves','♧'],['Boots','◢'],['Accessory','✧']];
const initial={gold:120,essence:5,gems:50,level:1,xp:0,atk:12,hp:100,def:3,crit:5,critDmg:150,speed:1,stage:1,region:0,kills:0,cleared:0,enemyHp:0,weaponLvl:0,enhance:0,pity:0,summons:0,auto:true,speedMode:1,activeTab:'battle',skillLvl:0,compLvl:1,companion:'Moonfox',companionOwned:['Moonfox'],activeComp:0,day:Math.floor(Date.now()/86400000),dungeonRuns:3,tower:1,quests:{kills:0,upgrade:0,summon:0},achievements:[],dungeonType:'Boss Dungeon',lastSeen:Date.now(),lastSave:Date.now(),boss:false};
let S;try{S={...initial,...JSON.parse(localStorage.getItem('eternalSlayerSave')||'{}')}}catch{S={...initial}}
const savedAt=S.lastSeen||Date.now(); let away=Math.min(12*3600,Math.max(0,(Date.now()-savedAt)/1000));
if(away>45){let rate=(S.level*3+S.stage*2+8), earned=Math.floor(rate*away/8);S.gold+=earned; S.xp+=Math.floor(earned*.45);S.kills+=Math.floor(away/12);window.addEventListener('load',()=>showOffline(away,earned));}
const save=()=>{S.lastSeen=Date.now();try{localStorage.setItem('eternalSlayerSave',JSON.stringify(S))}catch{}};
const fmt=n=>n>=1e9?(n/1e9).toFixed(1)+'B':n>=1e6?(n/1e6).toFixed(1)+'M':n>=1e4?(n/1e3).toFixed(1)+'K':Math.floor(n).toLocaleString();
const regionName=()=>regions[S.region][0];
const levelCost=()=>Math.floor(35*Math.pow(1.34,S.level-1));
const stageHp=()=>Math.floor((22+S.stage*14+S.region*100)*Math.pow(1.21,S.stage-1)*(S.boss?4.6:1));
if(!S.enemyHp||S.enemyHp<=0)S.enemyHp=stageHp();
let enemyMax=stageHp(),sceneTick=0,attackTimer=0,skillTimer=0, lastFrame=performance.now();
const rand=(a,b)=>Math.floor(Math.random()*(b-a+1)+a);
function render(){updateHUD();renderTab();save()}
function updateHUD(){
 $('#gold-value').textContent=fmt(S.gold);$('#gold-res').textContent=fmt(S.gold);$('#essence-value').textContent=fmt(S.essence);$('#gems-value').textContent=fmt(S.gems);
 $('#stage-name').textContent=regionName().toUpperCase();$('#stage-number').textContent=`${String(S.region+1).padStart(2,'0')} - ${String(S.stage).padStart(2,'0')}`;
 $('#hero-level').textContent=`LV. ${S.level}`;$('#hero-power').textContent=fmt(S.atk+S.weaponLvl*4+S.enhance*3);
 $('#hero-hp-text').textContent=`${fmt(S.hp)} / ${fmt(S.hp)}`;$('#hero-hp-bar').style.width='100%';$('#xp-bar').style.width=`${Math.min(100,S.xp/levelCost()*100)}%`;
 enemyMax=stageHp();if(S.enemyHp>enemyMax)S.enemyHp=enemyMax;
 $('#enemy-name').textContent=S.boss?regions[S.region][4].toUpperCase():regions[S.region][2+((S.kills+S.stage)%2)].toUpperCase();$('#enemy-type').textContent=`${S.boss?'BOSS':'BEAST'} · LV. ${Math.max(1,S.level+S.region*5)}`;
 $('#enemy-icon').textContent=S.boss?'♜':'☠';$('#enemy-count').textContent=S.boss?'BOSS':`${(S.kills%10)+1} / 10`;
 $('#enemy-hp-bar').style.width=`${Math.max(0,S.enemyHp/enemyMax*100)}%`;$('#progress-label').textContent=`${S.stage} / 20`;$('#stage-progress').style.width=`${S.stage/20*100}%`;
 $('#auto-btn').classList.toggle('active',S.auto);$('#auto-btn').innerHTML=`✦ AUTO <span>${S.auto?'ON':'OFF'}</span>`;
}
function renderTab(){const tab=S.activeTab,p=$('#content-panel');$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.tab===tab));
 if(tab==='battle')p.innerHTML=battlePanel();if(tab==='character')p.innerHTML=characterPanel();if(tab==='equipment')p.innerHTML=equipmentPanel();if(tab==='skills')p.innerHTML=skillsPanel();if(tab==='adventure')p.innerHTML=adventurePanel();if(tab==='more')p.innerHTML=morePanel();bindPanel();}
function battlePanel(){let cost=levelCost();return `<div class="panel-heading"><h2>ADVENTURE</h2><small>Auto-battle is ${S.auto?'active':'paused'}</small></div><div class="panel-card battle-card"><div class="battle-card-icon">⚔</div><div class="card-copy"><strong>${S.boss?'BOSS ENCOUNTER':'HUNTING IN '+regionName().toUpperCase()}</strong><small>Rewards: Gold · EXP · Mystic Shards</small></div><button class="primary-btn" data-act="sweep">${S.boss?'CHALLENGE':'AUTO FIGHT'}</button></div><div class="subrow"><span>Hero EXP <b>${fmt(S.xp)} / ${fmt(cost)}</b></span><span>Next level <b>ATK +${Math.ceil(S.level*.9)} · HP +10</b></span></div><div class="panel-card battle-card"><div class="battle-card-icon" style="color:#e5ba60">⬆</div><div class="card-copy"><strong>QUICK LEVEL UP</strong><small>Improve your base attributes</small></div><button class="primary-btn" data-act="levelup">${fmt(cost)} ◈</button></div>`}
function characterPanel(){let upgrades=[['ATK','⚔','Increase damage per hit',S.atk,Math.floor(32*Math.pow(1.24,S.atk-12)),'atk'],['HP','❤','Survive more attacks',S.hp,Math.floor(28*Math.pow(1.18,S.hp/100-1)),'hp'],['DEF','⬡','Reduce incoming damage',S.def,Math.floor(50*Math.pow(1.35,S.def-3)),'def'],['CRIT RATE','✦','Chance to deal critical hits',S.crit+'%',Math.floor(80*Math.pow(1.4,S.crit/5-1)),'crit'],['CRIT DMG','✧','Critical strike multiplier',S.critDmg+'%',Math.floor(95*Math.pow(1.28,S.critDmg/150-1)),'critDmg'],['ATTACK SPEED','➤','Strike more often',S.speed.toFixed(1)+'×',Math.floor(110*Math.pow(1.5,S.speed-1)),'speed']];return `<div class="panel-heading"><h2>HERO DEVELOPMENT</h2><small>${fmt(S.gold)} ◈</small></div><div class="region-banner"><span>♙</span><div><strong>ARIEL · ${promotion()}</strong><small>Level ${S.level} · Evolution ${Math.max(1,Math.floor((S.level-1)/20)+1)}</small></div><button class="small-btn" data-act="promote">PROMOTE</button></div><div class="upgrade-grid">${upgrades.map(u=>`<div class="upgrade-card"><div class="u-top"><span>${u[0]}</span><span class="u-icon">${u[1]}</span></div><small>${u[2]}</small><div class="u-bottom"><b>${typeof u[3]==='number'?fmt(u[3]):u[3]}</b><button class="primary-btn" data-act="stat" data-stat="${u[5]}" data-cost="${u[4]}">＋ ${fmt(u[4])}</button></div></div>`).join('')}</div><div class="stats-line"><span class="stat-pill">⚔ Total Power ${fmt(S.atk+S.weaponLvl*4+S.enhance*3)}</span><span class="stat-pill">✧ Crit ${S.crit}%</span><span class="stat-pill">♙ ${S.level} / EXP ${fmt(S.xp)}</span></div>`}
function promotion(){return ['Novice','Apprentice','Adept','Knight','Elite','Master','Legend','Saint','Divine'][Math.min(8,Math.floor((S.level-1)/10))]}
function equipmentPanel(){return `<div class="panel-heading"><h2>EQUIPMENT</h2><small>Enhancement +${S.enhance}</small></div><div class="equipment-list">${gearTypes.map((g,i)=>{let level=i===0?S.weaponLvl:Math.max(0,Math.floor(S.weaponLvl*.5));return `<div class="gear-row"><div class="item-icon">${g[1]}</div><div><strong class="${level?'rarity':''}">${level?['Common','Rare','Epic','Legendary','Mythic'][Math.min(4,Math.floor(level/3))]+' ':''}${['Duskblade','Warden Mail','Moon Circlet','Aether Grips','Swiftstep Boots','Star Pendant'][i]}</strong><small>+${level} · ${i===0?`ATK +${level*4}`:'Power +' +(level*2)}</small></div>${i===0?`<button class="primary-btn" data-act="weapon">UP ${Math.floor(60*Math.pow(1.3,S.weaponLvl))} ◈</button>`:''}</div>`}).join('')}</div><div class="panel-card battle-card" style="margin-top:9px"><div class="battle-card-icon">✧</div><div class="card-copy"><strong>ENHANCE EQUIPMENT</strong><small>Spend essence · +3 ATK each level</small></div><button class="primary-btn" data-act="enhance">${fmt(5+S.enhance*3)} ✧</button></div><div class="subrow"><span>Set bonus</span><b>Moonlit Set · +5% Crit DMG</b></div>`}
function skillsPanel(){let skills=[['Arcane Bolt','✦','Arcane','Blast the enemy every 9 seconds for 4× ATK.'],['Frost Nova','❄','Frost','Every 3rd attack deals 2× damage and slows.'],['Phoenix Oath','🔥','Passive','Gain +10% attack power.'],['Celestial Ward','☼','Passive','Regenerate 1% HP per second.']];return `<div class="panel-heading"><h2>SKILLS & TALENTS</h2><small>Skill power ${S.skillLvl+1}</small></div><div class="panel-card">${skills.map((x,i)=>`<div class="skill-row"><div class="skill-badge">${x[1]}</div><div class="skill-info"><strong>${x[0]} <span class="rarity-label">${x[2]}</span></strong><small>${x[3]}</small></div><button class="small-btn" data-act="skill" data-skill="${i}">${i<2?'UPGRADE':'LEARN'}</button></div>`).join('')}</div><div class="subrow"><span>Auto cast</span><b>Enabled · Skill triggers automatically</b></div><div class="panel-card battle-card"><div class="battle-card-icon">☯</div><div class="card-copy"><strong>SKILL TRAINING</strong><small>Increase active skill damage</small></div><button class="primary-btn" data-act="skillup">${fmt(20+S.skillLvl*25)} ◈</button></div>`}
function adventurePanel(){return `<div class="panel-heading"><h2>WORLD MAP</h2><small>Region ${S.region+1} / 10</small></div><div class="region-banner"><span>${regions[S.region][1]}</span><div><strong>${regionName().toUpperCase()}</strong><small>Stages ${S.stage}–20 · ${regions[S.region][2]} & ${regions[S.region][3]}</small></div><span style="margin-left:auto;color:#e5bb64">◆ ${S.region+1}</span></div><div class="stage-grid">${Array.from({length:20},(_,i)=>`<button class="stage-cell ${i+1===S.stage?'current':''} ${i+1>S.cleared+1+(S.region*20)?'locked':''}" data-act="stage" data-stage="${i+1}" ${i+1>S.cleared+1+(S.region*20)?'disabled':''}>${i+1}${(i+1)%5===0?'♜':''}</button>`).join('')}</div><div class="panel-heading" style="margin-top:10px"><h2>CHALLENGES</h2><small>${S.dungeonRuns} runs left today</small></div><div class="feature-grid">${[['Boss Dungeon','♜','Rare gear & shards'],['Gold Dungeon','◈','A chest of gold'],['Material Dungeon','✧','Awakening essence'],['Tower of Trials','♧','Floor '+S.tower+' · endless']].map((x,i)=>`<button class="feature-card" data-act="dungeon" data-dungeon="${i}"><span>${x[1]}</span><strong>${x[0]}</strong><small>${x[2]}</small></button>`).join('')}</div>`}
function morePanel(){return `<div class="panel-heading"><h2>ETERNAL GUILD</h2><small>Daily reset in ${Math.floor((86400000-Date.now()%86400000)/3600000)}h</small></div><div class="panel-heading"><h2>DAILY QUESTS</h2><small>${S.quests.kills}/30 kills</small></div><div class="panel-card">${[['Defeat 30 monsters','⚔',`${Math.min(30,S.quests.kills)} / 30`,S.quests.kills>=30,30],['Upgrade a stat 5 times','⬆',`${Math.min(5,S.quests.upgrade)} / 5`,S.quests.upgrade>=5,5],['Summon 3 times','✦',`${Math.min(3,S.quests.summon)} / 3`,S.quests.summon>=3,3]].map((q,i)=>`<div class="quest-row"><div class="skill-badge">${q[1]}</div><div class="skill-info"><strong>${q[0]}</strong><small>${q[2]} · Reward: ${i===0?'500':i===1?'300':'100'} gold</small></div>${q[3]?`<button class="small-btn" data-act="claim" data-quest="${i}">CLAIM</button>`:'<span class="subtle">◌</span>'}</div>`).join('')}</div><div class="panel-heading" style="margin-top:12px"><h2>COMPANIONS · ${S.activeComp}/3 ACTIVE</h2><button class="small-btn" data-act="summon">SUMMON</button></div><div class="panel-card">${S.companionOwned.map((c,i)=>`<div class="companion-row"><div class="skill-badge">${c==='Moonfox'?'🦊':c==='Wisp'?'🧚':c==='Ember Drake'?'🐉':'😇'}</div><div class="skill-info"><strong>${c} <span class="rarity-label">LV. ${S.compLvl}</span></strong><small>Companion · +${S.compLvl*2}% attack</small></div><button class="small-btn" data-act="companion">${S.activeComp?'ACTIVE':'EQUIP'}</button></div>`).join('')}</div><div class="panel-heading" style="margin-top:12px"><h2>ACHIEVEMENTS</h2><small>${S.achievements.length} / 4 complete</small></div><div class="feature-grid">${[['First Blood',S.kills>=1,'Defeat your first monster'],['Trailblazer',S.cleared>=10,'Clear 10 stages'],['Collector',S.summons>=10,'Summon 10 times'],['Rising Star',S.level>=10,'Reach level 10']].map(a=>`<div class="feature-card"><span>${a[1]?'✪':'◇'}</span><strong>${a[0]}</strong><small>${a[1]?'Completed':'In progress'} · ${a[2]}</small></div>`).join('')}</div>`}
function bindPanel(){ $$('[data-act]').forEach(b=>b.onclick=()=>action(b.dataset.act,b.dataset));}

function action(type,data={}){
 if(type==='levelup'){let c=levelCost();if(S.gold<c)return toast('Not enough gold');S.gold-=c;S.level++;S.atk+=Math.ceil(S.level*.9);S.hp+=10;S.xp=Math.max(0,S.xp-c*.15);if(S.level%10===0)toast(`Promotion unlocked: ${promotion()}!`);}
 if(type==='stat'){let k=data.stat,c=+data.cost;if(S.gold<c)return toast('Not enough gold');S.gold-=c;S.quests.upgrade++;if(k==='atk')S.atk+=2;if(k==='hp')S.hp+=20;if(k==='def')S.def+=1;if(k==='crit')S.crit=Math.min(75,S.crit+1);if(k==='critDmg')S.critDmg+=10;if(k==='speed')S.speed=Math.min(5,S.speed+.1);}
 if(type==='weapon'){let c=Math.floor(60*Math.pow(1.3,S.weaponLvl));if(S.gold<c)return toast('Not enough gold');S.gold-=c;S.weaponLvl++;S.atk+=4;}
 if(type==='enhance'){let c=5+S.enhance*3;if(S.essence<c)return toast(`Need ${c} essence`);S.essence-=c;S.enhance++;}
 if(type==='skillup'){let c=20+S.skillLvl*25;if(S.gold<c)return toast('Not enough gold');S.gold-=c;S.skillLvl++;}
 if(type==='skill'){if(+data.skill<2){let c=25+S.skillLvl*20;if(S.gold<c)return toast('Not enough gold');S.gold-=c;S.skillLvl++;}else if(S.essence<3)return toast('Need 3 essence');else{S.essence-=3;S.skillLvl++;}}
 if(type==='promote'){if(S.level<10)return toast('Reach level 10 to promote');let cost=S.level*30;if(S.gold<cost)return toast(`Promotion needs ${cost} gold`);S.gold-=cost;S.atk+=Math.ceil(S.atk*.12);S.hp+=50;toast(`${promotion()} promotion complete!`)}
 if(type==='stage'){let st=+data.stage;if(st>S.cleared+1+(S.region*20))return;if(st===20&&S.region<9&&S.cleared<S.region*20+20)return toast('Clear stages in order');S.stage=st;S.boss=st%5===0;S.enemyHp=stageHp();}
 if(type==='dungeon'){let i=+data.dungeon;if(S.dungeonRuns<1)return toast('No runs left today. Come back tomorrow!');S.dungeonRuns--;let reward=[['boss',rand(35,65),rand(3,8)],['gold',rand(200,460),0],['material',0,rand(3,7)],['tower',rand(80,130),rand(1,3)]][i];S.gold+=reward[1];S.essence+=reward[2];if(i===3)S.tower++;toast(`${['Boss clear!','Gold haul!','Materials found!','Tower floor cleared!'][i]} +${reward[1]} gold · +${reward[2]} essence`);}
 if(type==='summon'){openSummon();return}
 if(type==='claim'){let i=+data.quest,complete=[S.quests.kills>=30,S.quests.upgrade>=5,S.quests.summon>=3][i];if(!complete)return toast('Quest not complete');if(S.quests['claimed'+i])return toast('Already claimed');S.quests['claimed'+i]=true;S.gold+=i===0?500:i===1?300:100;S.gems+=10;toast('Quest claimed · +10 gems')}
 if(type==='companion'){S.activeComp=Math.min(3,S.activeComp+1);toast('Companion equipped')}
 if(type==='sweep'){if(S.boss){S.enemyHp=1;killEnemy()}else S.auto=!S.auto;}
 render();
}
function openSummon(){let root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop" data-close><section class="modal"><div class="modal-head"><h2>SUMMON ALTAR</h2><button class="close-btn" data-close>×</button></div><p>Call forth heroes and relics from beyond the veil. Each summon increases your pity meter. Guaranteed Legendary at 30 summons.</p><div class="subrow"><span>Pity</span><b>${S.pity} / 30</b></div><div class="summon-options"><div class="summon-card"><span>⚔</span><strong>Relic Summon</strong><small>Weapon · Armor · Accessories</small><button class="primary-btn" data-pull="gear">SUMMON · 25 ◈</button></div><div class="summon-card"><span>✦</span><strong>Companion Summon</strong><small>Fairy · Dragon · Demon</small><button class="primary-btn" data-pull="companion">SUMMON · 35 ◈</button></div><div class="summon-card"><span>❄</span><strong>Skill Summon</strong><small>Unlock elemental skills</small><button class="primary-btn" data-pull="skill">SUMMON · 20 ◈</button></div><div class="summon-card"><span>✧</span><strong>10× Relic</strong><small>One guaranteed Rare+</small><button class="primary-btn" data-pull="ten">10× · 225 ◈</button></div></div></section></div>`;
 root.querySelectorAll('[data-close]').forEach(x=>x.onclick=e=>{if(e.target===x||x.classList.contains('close-btn'))root.innerHTML=''});root.querySelectorAll('[data-pull]').forEach(x=>x.onclick=()=>pull(x.dataset.pull));}
function pull(type){let cost=type==='companion'?35:type==='skill'?20:type==='ten'?225:25;if(S.gems<cost)return toast('Not enough gems');S.gems-=cost;let n=type==='ten'?10:1,items=[];for(let i=0;i<n;i++){S.summons++;S.pity++;let guaranteed=S.pity>=30;let roll=Math.random(),r=guaranteed||roll<.01?'Legendary':roll<.13?'Epic':roll<.42?'Rare':'Common';if(guaranteed)S.pity=0;
 if(type==='companion'){let c=roll<.12?'Ember Drake':roll<.45?'Wisp':'Moonfox';if(!S.companionOwned.includes(c))S.companionOwned.push(c);else S.compLvl++;items.push(`${r} ${c}`)}else if(type==='skill'){S.skillLvl++;items.push(`${r} Elemental skill`)}else {if(r==='Legendary'||r==='Epic'){S.weaponLvl++;S.atk+=4}items.push(`${r} Relic`)}}
 S.quests.summon+=n;$('#modal-root').innerHTML='';toast(`Summoned ${items.slice(0,3).join(', ')}${items.length>3?` +${items.length-3} more`:''}`);render();}
function toast(msg){let t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),2300)}
function showOffline(seconds,gold){let hours=Math.floor(seconds/3600),mins=Math.floor(seconds%3600/60);$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-head"><h2>WELCOME BACK, SLAYER</h2><button class="close-btn" data-close>×</button></div><div class="region-banner"><span>🌙</span><div><strong>AWAY FOR ${hours?hours+'H ':''}${mins}M</strong><small>Your hero kept fighting while you were away.</small></div></div><div class="panel-card"><div class="subrow"><span>Gold collected</span><b>+${fmt(gold)} ◈</b></div><div class="subrow"><span>Experience gained</span><b>+${fmt(Math.floor(gold*.45))} EXP</b></div><div class="subrow"><span>Materials found</span><b>+${Math.floor(seconds/1800)} essence</b></div></div><button class="primary-btn" style="width:100%;margin-top:12px" data-close>CLAIM REWARDS</button></section></div>`;S.essence+=Math.floor(seconds/1800);$('#modal-root').querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>$('#modal-root').innerHTML='');}
$$('.nav-item').forEach(n=>n.onclick=()=>{S.activeTab=n.dataset.tab;render()});$('#quest-shortcut').onclick=()=>{S.activeTab='more';render()};$('#settings-btn').onclick=()=>settings();$('#auto-btn').onclick=()=>{S.auto=!S.auto;render()};$('#advance-btn').onclick=()=>nextStage(true);$('#speed-btn').onclick=()=>{S.speedMode=S.speedMode===1?2:S.speedMode===2?3:1;$('#speed-btn').innerHTML=`Ⅱ <span>${S.speedMode}×</span>`;toast(`Battle speed ${S.speedMode}×`)};
function settings(){let root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-head"><h2>SETTINGS</h2><button class="close-btn" data-close>×</button></div><div class="panel-card"><div class="subrow"><span>Auto battle</span><b>${S.auto?'ON':'OFF'}</b></div><div class="subrow"><span>Cloud save</span><b>Local device save active</b></div><div class="subrow"><span>Idle cap</span><b>12 hours</b></div></div><p>Your progress saves automatically on this device.</p><button class="primary-btn" id="reset-save" style="background:linear-gradient(135deg,#9b526d,#6c354a)">RESET GAME</button></section></div>`;root.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>root.innerHTML='');$('#reset-save').onclick=()=>{if(confirm('Delete all Eternal Slayer progress?')){localStorage.removeItem('eternalSlayerSave');location.reload()}}}
function nextStage(user=false){if(S.stage<20){S.cleared=Math.max(S.cleared,S.region*20+S.stage);S.stage++;S.boss=S.stage%5===0;}else if(S.region<9){if(S.cleared<S.region*20+20){if(user)toast('Defeat the region boss first');return}S.region++;S.stage=1;S.boss=false;toast(`New region unlocked: ${regionName()}`)}else{S.stage=20;S.boss=true;if(user)toast('The Eternal Dragon awaits!')}S.enemyHp=stageHp();render()}
function levelGain(amount){S.xp+=amount;while(S.xp>=levelCost()){S.xp-=levelCost();S.level++;S.atk+=Math.ceil(S.level*.9);S.hp+=10;if(S.level%10===0)toast(`Level up! ${promotion()} reached.`)}}
function killEnemy(){S.kills++;S.quests.kills++;let boss=S.boss;let gold=Math.floor((10+S.stage*3+S.region*20)*(boss?8:1)*(1+S.level*.03));S.gold+=gold;S.essence+=boss?rand(1,3):Math.random()<.14?1:0;levelGain(Math.floor((7+S.stage*2+S.region*12)*(boss?6:1)));$('#loot-toast').innerHTML=`+${fmt(gold)} GOLD <span>✦</span>`;$('#loot-toast').classList.remove('show');void $('#loot-toast').offsetWidth;$('#loot-toast').classList.add('show');if(boss){S.cleared=Math.max(S.cleared,S.region*20+S.stage);toast('Boss defeated · stage cleared!');nextStage()}else{if(S.kills%10===0){S.boss=true;S.enemyHp=stageHp();}else S.enemyHp=stageHp();}updateHUD()}
