function floatDamage(dmg,crit){let el=document.createElement('span');el.className='damage-number'+(crit?' crit':'');el.textContent=(crit?'CRIT ':'')+fmt(dmg);el.style.left=`${rand(53,78)}%`;el.style.top=`${rand(32,50)}%` ;$('#combat-float').appendChild(el);setTimeout(()=>el.remove(),1000)}
function skillCast(){let el=document.createElement('span');el.className='skill-flash';el.textContent=['✦','❄','🔥'][S.skillLvl%3];$('#combat-float').appendChild(el);setTimeout(()=>el.remove(),500);let dmg=(S.atk+S.weaponLvl*4)*4*(1+S.skillLvl*.12);S.enemyHp-=dmg;floatDamage(dmg,false);if(S.enemyHp<=0)killEnemy()}
function updateGame(now){let dt=Math.min(.1,(now-lastFrame)/1000);lastFrame=now;sceneTick+=dt;drawScene();if(S.auto){attackTimer+=dt*S.speedMode;skillTimer+=dt*S.speedMode;if(attackTimer>=Math.max(.32,1/S.speed)){attackTimer=0;hit()}if(skillTimer>=10){skillTimer=0;skillCast()}}requestAnimationFrame(updateGame)}

const canvas=$('#scene'),ctx=canvas.getContext('2d');
function drawScene(){let w=canvas.width,h=canvas.height,t=sceneTick,zone=S.region;ctx.clearRect(0,0,w,h);
 // dusk sky and distant layered mountains
 let sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,['#192344','#241b3c','#142538','#14223b','#30223a','#181d42','#302235','#241b36','#341a2b','#182447'][zone]);sky.addColorStop(.58,'#30304d');sky.addColorStop(1,'#182032');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
 for(let layer=0;layer<3;layer++){ctx.beginPath();ctx.moveTo(0,h*(.42+layer*.09));for(let x=0;x<=w;x+=60){let yy=h*(.38+layer*.1)+Math.sin(x*.012+layer*2+zone)*30+Math.sin(x*.026+layer)*13;ctx.lineTo(x,yy)}ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();ctx.fillStyle=['#252b46','#1c263d','#152238'][layer];ctx.fill()}
 // moon / eclipse and stars
 ctx.globalAlpha=.72;ctx.fillStyle=zone%3===0?'#ead9b5':'#c3c0e8';ctx.shadowColor='#9b9be0';ctx.shadowBlur=28;ctx.beginPath();ctx.arc(555,88,28,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.globalAlpha=1;
 for(let i=0;i<35;i++){let x=(i*127+43)%w,y=(i*61+20)%190;ctx.fillStyle=`rgba(232,222,255,${.35+.3*Math.sin(t+i)})`;ctx.fillRect(x,y,2,2)}
 // ruined arch silhouette
 ctx.fillStyle='#11192b';ctx.fillRect(75,149,18,135);ctx.fillRect(194,145,17,142);ctx.fillRect(64,142,154,16);ctx.fillRect(82,135,12,8);ctx.fillRect(192,134,12,10);ctx.fillStyle='#25243c';ctx.fillRect(94,159,99,10);
 // terrain and pixel highlights
 ctx.fillStyle='#101a25';ctx.beginPath();ctx.moveTo(0,335);ctx.quadraticCurveTo(180,300,330,341);ctx.quadraticCurveTo(510,375,720,316);ctx.lineTo(720,560);ctx.lineTo(0,560);ctx.closePath();ctx.fill();
 ctx.fillStyle='#22303b';for(let i=0;i<15;i++){let x=(i*67+((t*8)%67))%w;ctx.fillRect(x,392+(i%4)*19,randStatic(i,12,29),3)}
 // plants and glowy flowers
 for(let i=0;i<12;i++){let x=(i*73+21)%w,y=367+(i%3)*23;ctx.fillStyle=i%2?'#203f3c':'#293749';ctx.fillRect(x,y,5,20);ctx.fillRect(x-5,y+7,15,4);ctx.fillStyle=i%2?'#9b80d1':'#6dc8bd';ctx.globalAlpha=.65;ctx.fillRect(x-2,y-2,4,4);ctx.globalAlpha=1}
 // hero and companion
