 // magic motes
 for(let i=0;i<16;i++){let x=(i*113+Math.sin(t*1.1+i)*13)%w,y=250+((i*73+t*11)%230);ctx.fillStyle=i%3?'#a882ef':'#8de1ca';ctx.globalAlpha=.15+.2*Math.sin(t*2+i);ctx.fillRect(x,y,3,3);ctx.globalAlpha=1}
}
