function drawHero(x,y,t){let bob=Math.sin(t*4)*2;ctx.save();ctx.translate(x,y+bob); // cape
 ctx.fillStyle='#542d64';ctx.beginPath();ctx.moveTo(-12,-37);ctx.lineTo(-27,4);ctx.lineTo(7,1);ctx.lineTo(10,-36);ctx.closePath();ctx.fill();ctx.fillStyle='#a5a9c5';ctx.fillRect(-10,-48,20,19);ctx.fillStyle='#f0c4ae';ctx.fillRect(-7,-61,14,14);ctx.fillStyle='#252a4c';ctx.fillRect(-8,-64,16,6);ctx.fillRect(-10,-59,4,10);ctx.fillStyle='#202743';ctx.fillRect(-10,-29,21,30);ctx.fillStyle='#baa2e8';ctx.fillRect(-4,-46,8,2);ctx.fillStyle='#d9e1ef';ctx.fillRect(8,-38,3,30);ctx.save();ctx.translate(10,-28);ctx.rotate(Math.sin(t*3)*.1-.1);ctx.fillStyle='#cbd3e6';ctx.fillRect(0,-29,3,36);ctx.fillStyle='#8c70c9';ctx.fillRect(-2,3,7,3);ctx.restore();ctx.fillStyle='#d5bc73';ctx.fillRect(-8,0,7,10);ctx.fillRect(3,0,7,10);ctx.restore()}
function drawCompanion(x,y,t){let bob=Math.sin(t*5+1)*4;ctx.save();ctx.translate(x,y+bob);ctx.fillStyle='#bba1f0';ctx.globalAlpha=.4;ctx.beginPath();ctx.arc(0,-10,17,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#d1c0ff';ctx.beginPath();ctx.arc(0,-10,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#edda9e';ctx.fillRect(-10,-23,5,8);ctx.fillRect(5,-23,5,8);ctx.fillStyle='#392d56';ctx.fillRect(-4,-12,2,2);ctx.fillRect(3,-12,2,2);ctx.restore()}
function drawMonster(x,y,t,boss){ctx.save();ctx.translate(x,y+Math.sin(t*3)*3);let s=boss?1.55:1;ctx.scale(s,s);if(boss){ctx.fillStyle='#402e52';ctx.fillRect(-31,-47,62,47);ctx.fillStyle='#765398';ctx.fillRect(-27,-58,10,19);ctx.fillRect(18,-58,10,19);ctx.fillStyle='#ac78b3';ctx.fillRect(-20,-40,40,30);ctx.fillStyle='#f2a379';ctx.fillRect(-13,-31,6,5);ctx.fillRect(8,-31,6,5);ctx.fillStyle='#352842';ctx.fillRect(-32,-12,15,19);ctx.fillRect(17,-12,15,19);ctx.fillStyle='#d1a2ed';ctx.fillRect(-22,-59,5,9);ctx.fillRect(18,-59,5,9);ctx.fillStyle='#be8bdb';ctx.fillRect(-39,-17,9,6);ctx.fillRect(29,-17,9,6)}else{ctx.fillStyle='#654c82';ctx.beginPath();ctx.ellipse(0,-12,25,19,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b29bd4';ctx.fillRect(-14,-29,28,14);ctx.fillStyle='#f3d288';ctx.fillRect(-8,-24,5,5);ctx.fillRect(6,-24,5,5);ctx.fillStyle='#47375c';ctx.fillRect(-19,2,10,7);ctx.fillRect(10,2,10,7);ctx.fillStyle='#91cebd';ctx.fillRect(-21,-10,4,5)}ctx.restore()}
function bindCanvasResize(){/* canvas scales responsively through CSS; fixed internal pixel grid keeps art crisp */}
requestAnimationFrame(updateGame);render();setInterval(()=>{if(Math.floor(Date.now()/86400000)!==S.day){S.day=Math.floor(Date.now()/86400000);S.dungeonRuns=3;S.quests={kills:0,upgrade:0,summon:0};toast('Daily challenges refreshed!')}updateHUD();save()},5000);
window.addEventListener('beforeunload',save);
})();

