(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const regions=[['Whispering Woods','🌲','Mossling','Thornfang','Elder Treant'],['Ashen Highlands','🌋','Cinder Wisp','Ember Hound','Pyre Drake'],['Frostfall Reach','❄','Snow Wraith','Ice Troll','Glacier Titan'],['Sunken Kingdom','🌊','Drowned Guard','Tide Siren','Abyssal King'],['Eclipse Desert','☀','Dune Stalker','Sand Djinn','Sphinx of Dusk'],['Astral Spire','🌌','Voidling','Star Knight','Astral Seraph'],['Wyrmfire Peaks','🐉','Drakelet','Flame Basilisk','Ancient Wyrm'],['Hollow Cathedral','⛪','Fallen Acolyte','Doom Priest','Hollow Saint'],['Demon Realm','🔥','Hellspawn','Dread Fiend','Demon Sovereign'],['Eternal Citadel','🏰','Aether Warden','Celestial Knight','Eternal Dragon']];
const initial={gold:120,essence:5,gems:50,level:1,xp:0,atk:12,hp:100,def:3,crit:5,critDmg:150,speed:1,stage:1,region:0,kills:0,cleared:0,enemyHp:0,weaponLvl:0,enhance:0,pity:0,summons:0,auto:true,speedMode:1,activeTab:'battle',skillLvl:0,compLvl:1,companionOwned:['Moonfox'],activeComp:0,day:Math.floor(Date.now()/86400000),dungeonRuns:3,tower:1,quests:{kills:0,upgrade:0,summon:0},achievements:[],lastSeen:Date.now(),boss:false};
let S;try{S={...initial,...JSON.parse(localStorage.getItem('eternalSlayerSave')||'{}')}}catch{S={...initial}};const away=Math.min(43200,Math.max(0,(Date.now()-(S.lastSeen||Date.now()))/1000));
if(away>45){let g=Math.floor((S.level*3+S.stage*2+8)*away/8);S.gold+=g;S.xp+=Math.floor(g*.45);S.essence+=Math.floor(away/1800);window.addEventListener('load',()=>offlineModal(away,g))}
const save=()=>{S.lastSeen=Date.now();try{localStorage.setItem('eternalSlayerSave',JSON.stringify(S))}catch{}};const fmt=n=>n>=1e9?(n/1e9).toFixed(1)+'B':n>=1e6?(n/1e6).toFixed(1)+'M':n>=1e4?(n/1e3).toFixed(1)+'K':Math.floor(n).toLocaleString();const regionName=()=>regions[S.region][0];const levelCost=()=>Math.floor(35*Math.pow(1.34,S.level-1));const stageHp=()=>Math.floor((22+S.stage*14+S.region*100)*Math.pow(1.21,S.stage-1)*(S.boss?4.6:1));const rand=(a,b)=>Math.floor(Math.random()*(b-a+1)+a);if(!S.enemyHp)S.enemyHp=stageHp();
let sceneTick=0,attackTimer=0,skillTimer=0,lastFrame=performance.now();
function promotion(){return ['Novice','Apprentice','Adept','Knight','Elite','Master','Legend','Saint','Divine'][Math.min(8,Math.floor((S.level-1)/10))]}
function updateHUD(){$('#gold-value').textContent=fmt(S.gold);$('#gold-res').textContent=fmt(S.gold);$('#essence-value').textContent=fmt(S.essence);$('#gems-value').textContent=fmt(S.gems);$('#stage-name').textContent=regionName().toUpperCase();$('#stage-number').textContent=`${String(S.region+1).padStart(2,'0')} - ${String(S.stage).padStart(2,'0')}`;$('#hero-level').textContent=`LV. ${S.level}`;$('#hero-power').textContent=fmt(S.atk+S.weaponLvl*4+S.enhance*3);$('#hero-hp-text').textContent=`${fmt(S.hp)} / ${fmt(S.hp)}`;$('#xp-bar').style.width=`${Math.min(100,S.xp/levelCost()*100)}%`;let max=stageHp();$('#enemy-name').textContent=S.boss?regions[S.region][4].toUpperCase():regions[S.region][2+((S.kills+S.stage)%2)].toUpperCase();$('#enemy-type').textContent=`${S.boss?'BOSS':'BEAST'} · LV. ${Math.max(1,S.level+S.region*5)}`;$('#enemy-icon').textContent=S.boss?'♜':'☠';$('#enemy-count').textContent=S.boss?'BOSS':`${S.kills%10+1} / 10`;$('#enemy-hp-bar').style.width=`${Math.max(0,S.enemyHp/max*100)}%`;$('#progress-label').textContent=`${S.stage} / 20`;$('#stage-progress').style.width=`${S.stage/20*100}%`;$('#auto-btn').classList.toggle('active',S.auto);$('#auto-btn').innerHTML=`✦ AUTO <span>${S.auto?'ON':'OFF'}</span>`}
