function battlePanel(){return `<div class="panel-heading"><h2>ADVENTURE</h2><small>Auto-battle ${S.auto?'active':'paused'}</small></div><div class="panel-card battle-card"><div class="battle-card-icon">⚔</div><div class="card-copy"><strong>${S.boss?'BOSS ENCOUNTER':'HUNTING IN '+regionName().toUpperCase()}</strong><small>Rewards: Gold · EXP · Mystic Shards</small></div><button class="primary-btn" data-act="sweep">${S.boss?'CHALLENGE':'AUTO FIGHT'}</button></div><div class="subrow"><span>Hero EXP <b>${fmt(S.xp)} / ${fmt(levelCost())}</b></span><span>Level ${S.level}</span></div><div class="panel-card battle-card"><div class="battle-card-icon" style="color:#e5ba60">⬆</div><div class="card-copy"><strong>QUICK LEVEL UP</strong><small>Improve your base attributes</small></div><button class="primary-btn" data-act="levelup">${fmt(levelCost())} ◈</button></div>`}
