function equipmentPanel(){let g=[['Weapon','⚔','Duskblade'],['Armor','▣','Warden Mail'],['Helmet','◈','Moon Circlet'],['Gloves','♧','Aether Grips'],['Boots','◢','Swiftstep Boots'],['Accessory','✧','Star Pendant']];return `<div class="panel-heading"><h2>EQUIPMENT</h2><small>Enhancement +${S.enhance}</small></div><div class="equipment-list">${g.map((x,i)=>`<div class="gear-row"><div class="item-icon">${x[1]}</div><div><strong class="${S.weaponLvl?'rarity':''}">${S.weaponLvl?'Rare ':''}${x[2]}</strong><small>+${i?Math.floor(S.weaponLvl/2):S.weaponLvl} · Power +${i?S.weaponLvl*2:S.weaponLvl*4}</small></div>${i===0?`<button class="primary-btn" data-act="weapon">UP ${Math.floor(60*Math.pow(1.3,S.weaponLvl))} ◈</button>`:''}</div>`).join('')}</div><div class="panel-card battle-card" style="margin-top:9px"><div class="battle-card-icon">✧</div><div class="card-copy"><strong>ENHANCE EQUIPMENT</strong><small>Spend essence · +3 ATK each level</small></div><button class="primary-btn" data-act="enhance">${5+S.enhance*3} ✧</button></div><div class="subrow"><span>Summon relics and gear</span><button class="small-btn" data-act="summon">SUMMON</button></div>`}
