function adventurePanel(){return `<div class="panel-heading"><h2>WORLD MAP</h2><small>Region ${S.region+1} / 10</small></div><div class="region-banner"><span>${regions[S.region][1]}</span><div><strong>${regionName().toUpperCase()}</strong><small>Stages ${S.stage}–20 · ${regions[S.region][2]} & ${regions[S.region][3]}</small></div></div><div class="stage-grid">${Array.from({length:20},(_,i)=>`<button class="stage-cell ${i+1===S.stage?'current':''} ${i+1>S.stage?'locked':''}" data-act="stage" data-stage="${i+1}" ${i+1>S.stage?'disabled':''}>${i+1}${(i+1)%5===0?'♜':''}</button>`).join('')}</div><div class="panel-heading" style="margin-top:10px"><h2>CHALLENGES</h2><small>${S.dungeonRuns} runs left today</small></div><div class="feature-grid">${[['Boss Dungeon','♜','Rare gear & shards'],['Gold Dungeon','◈','A chest of gold'],['Material Dungeon','✧','Awakening essence'],['Tower of Trials','♧','Floor '+S.tower+' · endless']].map((x,i)=>`<button class="feature-card" data-act="dungeon" data-dungeon="${i}"><span>${x[1]}</span><strong>${x[0]}</strong><small>${x[2]}</small></button>`).join('')}</div>`}
function morePanel(){let q=[['Defeat 30 monsters','⚔',Math.min(30,S.quests.kills),30],['Upgrade stats 5 times','⬆',Math.min(5,S.quests.upgrade),5],['Summon 3 times','✦',Math.min(3,S.quests.summon),3]];return `<div class="panel-heading"><h2>DAILY QUESTS</h2><small>Reset daily · ${S.quests.kills}/30 kills</small></div><div class="panel-card">${q.map((x,i)=>`<div class="quest-row"><div class="skill-badge">${x[1]}</div><div class="skill-info"><strong>${x[0]}</strong><small>${x[2]} / ${x[3]} · Reward: ${i===0?500:i===1?300:100} gold + 10 gems</small></div>${x[2]>=x[3]&&!S.quests['c'+i]?`<button class="small-btn" data-act="claim" data-q="${i}">CLAIM</button>`:'<span class="subtle">◌</span>'}</div>`).join('')}</div><div class="panel-heading" style="margin-top:12px"><h2>COMPANIONS · ${S.activeComp}/3 ACTIVE</h2><button class="small-btn" data-act="summon">SUMMON</button></div><div class="panel-card">${S.companionOwned.map(c=>`<div class="companion-row"><div class="skill-badge">${c==='Moonfox'?'🦊':c==='Wisp'?'🧚':'🐉'}</div><div class="skill-info"><strong>${c} · LV. ${S.compLvl}</strong><small>Companion · +${S.compLvl*2}% attack</small></div><button class="small-btn" data-act="companion">${S.activeComp?'ACTIVE':'EQUIP'}</button></div>`).join('')}</div><div class="panel-heading" style="margin-top:12px"><h2>ACHIEVEMENTS</h2><small>Milestones</small></div><div class="feature-grid">${[['First Blood',S.kills>=1],['Trailblazer',S.cleared>=10],['Collector',S.summons>=10],['Rising Star',S.level>=10]].map(a=>`<div class="feature-card"><span>${a[1]?'✪':'◇'}</span><strong>${a[0]}</strong><small>${a[1]?'Completed':'In progress'}</small></div>`).join('')}</div>`}
function bindPanel(){$$('[data-act]').forEach(b=>b.onclick=()=>action(b.dataset.act,b.dataset))}
function action(type,d={}){if(type==='levelup'){let c=levelCost();if(S.gold<c)return toast('Not enough gold');S.gold-=c;S.level++;S.atk+=Math.ceil(S.level*.9);S.hp+=10;S.xp=Math.max(0,S.xp-c*.15)}if(type==='stat'){let k=d.stat,c=+d.cost;if(S.gold<c)return toast('Not enough gold');S.gold-=c;S.quests.upgrade++;if(k==='atk')S.atk+=2;if(k==='hp')S.hp+=20;if(k==='def')S.def++;if(k==='crit')S.crit=Math.min(75,S.crit+1);if(k==='critDmg')S.critDmg+=10;if(k==='speed')S.speed=Math.min(5,S.speed+.1)}if(type==='weapon'){let c=Math.floor(60*Math.pow(1.3,S.weaponLvl));if(S.gold<c)return toast('Not enough gold');S.gold-=c;S.weaponLvl++;S.atk+=4}if(type==='enhance'){let c=5+S.enhance*3;if(S.essence<c)return toast(`Need ${c} essence`);S.essence-=c;S.enhance++}if(type==='skillup'||type==='skill'){let c=type==='skillup'?20+S.skillLvl*25:25+S.skillLvl*20;if(+d.skill>=2)c=0;if(S.gold<c)return toast('Not enough gold');S.gold-=c;S.skillLvl++}if(type==='promote'){if(S.level<10)return toast('Reach level 10 to promote');let c=S.level*30;if(S.gold<c)return toast('Not enough gold');S.gold-=c;S.atk+=Math.ceil(S.atk*.12);S.hp+=50;toast(`${promotion()} promotion complete!`)}if(type==='stage'&&+d.stage<=S.stage){S.stage=+d.stage;S.boss=false;S.enemyHp=stageHp()}if(type==='dungeon'){if(S.dungeonRuns<1)return toast('No runs left today');S.dungeonRuns--;let i=+d.dungeon,g=[rand(35,65),rand(200,460),0,rand(80,130)][i],e=[rand(3,8),0,rand(3,7),rand(1,3)][i];S.gold+=g;S.essence+=e;if(i===3)S.tower++;if(i===0){S.weaponLvl++;S.atk+=4}toast(`Dungeon clear · +${g} gold · +${e} essence`)}if(type==='summon'){openSummon();return}if(type==='claim'){let i=+d.q,need=[30,5,3][i],val=[S.quests.kills,S.quests.upgrade,S.quests.summon][i];if(val<need||S.quests['c'+i])return toast('Quest not ready');S.quests['c'+i]=true;S.gold+=i===0?500:i===1?300:100;S.gems+=10;toast('Quest claimed · +10 gems')}if(type==='companion'){S.activeComp=Math.min(3,S.activeComp+1);toast('Companion equipped')}if(type==='sweep'){if(S.boss){S.enemyHp=1;killEnemy()}else S.auto=!S.auto}render()}
function openSummon(){let r=$('#modal-root');r.innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-head"><h2>SUMMON ALTAR</h2><button class="close-btn" data-close>×</button></div><p>Summon relics, elemental skills, and companions. Pity guarantees Legendary after 30 pulls.</p><div class="subrow"><span>Pity</span><b>${S.pity}/30</b></div><div class="summon-options">${[['gear','⚔','Relic Summon',25],['companion','🦊','Companion Summon',35],['skill','✦','Skill Summon',20],['ten','✧','10× Relic',225]].map(x=>`<div class="summon-card"><span>${x[1]}</span><strong>${x[2]}</strong><small>Every pull adds pity</small><button class="primary-btn" data-pull="${x[0]}">${x[0]==='ten'?'10× · ':''}SUMMON · ${x[3]} ◉</button></div>`).join('')}</div></section></div>`;r.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>r.innerHTML='');r.querySelectorAll('[data-pull]').forEach(x=>x.onclick=()=>pull(x.dataset.pull))}
function pull(type){let c=type==='companion'?35:type==='skill'?20:type==='ten'?225:25;if(S.gems<c)return toast('Not enough gems');S.gems-=c;let n=type==='ten'?10:1,out=[];for(let i=0;i<n;i++){S.summons++;S.pity++;let roll=Math.random(),rar=S.pity>=30||roll<.01?'Legendary':roll<.13?'Epic':roll<.42?'Rare':'Common';if(S.pity>=30)S.pity=0;if(type==='companion'){let pet=roll<.15?'Ember Drake':roll<.5?'Wisp':'Moonfox';if(S.companionOwned.includes(pet))S.compLvl++;else S.companionOwned.push(pet);out.push(`${rar} ${pet}`)}else if(type==='skill'){S.skillLvl++;out.push(`${rar} Skill`)}else{if(rar==='Legendary'||rar==='Epic'){S.weaponLvl++;S.atk+=4}out.push(`${rar} Relic`)}}S.quests.summon+=n;$('#modal-root').innerHTML='';toast('Summoned '+out.slice(0,3).join(', ')+(n>3?'…':''));render()}
function toast(m){let e=document.createElement('div');e.className='toast';e.textContent=m;document.body.appendChild(e);setTimeout(()=>e.remove(),2200)}
function offlineModal(sec,g){let h=Math.floor(sec/3600),m=Math.floor(sec%3600/60);$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-head"><h2>WELCOME BACK, SLAYER</h2><button class="close-btn" data-close>×</button></div><div class="region-banner"><span>🌙</span><div><strong>AWAY ${h?`${h}H `:''}${m}M</strong><small>Your hero kept fighting.</small></div></div><div class="panel-card"><div class="subrow"><span>Gold collected</span><b>+${fmt(g)} ◈</b></div><div class="subrow"><span>Experience gained</span><b>+${fmt(Math.floor(g*.45))} EXP</b></div><div class="subrow"><span>Materials found</span><b>+${Math.floor(sec/1800)} essence</b></div></div><button class="primary-btn" style="width:100%;margin-top:12px" data-close>CLAIM REWARDS</button></section></div>`;$('#modal-root').querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>$('#modal-root').innerHTML='')}

