import { spawn } from 'node:child_process';
const proc=spawn('chromium',['--headless','--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--remote-debugging-port=9224','--user-data-dir=/tmp/opencode/chrome-progression-test','about:blank'],{stdio:'ignore'});
const wait=ms=>new Promise(r=>setTimeout(r,ms));let targets;
for(let i=0;i<40;i++){try{targets=await(await fetch('http://127.0.0.1:9224/json')).json();break}catch{await wait(250)}}
if(!targets)throw Error('Chrome debug endpoint did not start');
const ws=new WebSocket(targets.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});
let id=0;const pending=new Map(),errors=[];ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
const call=(method,params={})=>new Promise(resolve=>{let n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
const ev=async expression=>(await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result.result.value;
await call('Page.enable');await call('Runtime.enable');await call('Page.navigate',{url:'file:///home/runner/work/PlayGround/PlayGround/index.html'});await wait(700);
await call('Page.addScriptToEvaluateOnNewDocument',{source:"(()=>{let s=JSON.parse(localStorage.getItem('eternalSlayerSave')||'{}');Object.assign(s,{stage:5,region:0,kills:9,stageKills:9,boss:false,enemyHp:1,atk:1000,auto:false,lastSeen:Date.now()});localStorage.setItem('eternalSlayerSave',JSON.stringify(s))})()"});
await call('Page.reload',{});await wait(500);
await ev("document.querySelector('[data-tab=battle]').click()");
await ev("document.querySelector('[data-act=sweep]').click()");
const boss=await ev("JSON.parse(localStorage.getItem('eternalSlayerSave'))");
await ev("document.querySelector('[data-act=sweep]').click()");
const progressed=await ev("JSON.parse(localStorage.getItem('eternalSlayerSave'))");
await call('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});await wait(200);
const mobile=await ev("({width:innerWidth,docWidth:document.documentElement.scrollWidth,bodyWidth:document.body.scrollWidth,shell:document.querySelector('.game-shell').getBoundingClientRect().width,content:document.querySelector('#content-panel').getBoundingClientRect().width,tab:document.querySelector('.panel-heading h2')?.textContent})");
console.log(JSON.stringify({boss:{stage:boss.stage,boss:boss.boss,stageKills:boss.stageKills,kills:boss.kills},progressed:{region:progressed.region,stage:progressed.stage,boss:progressed.boss,cleared:progressed.cleared,kills:progressed.kills},mobile,errors},null,2));
ws.close();proc.kill();

