await load({stage:20,region:0,kills:9,stageKills:9,boss:true,enemyHp:1,atk:1000000,auto:false,lastSeen:Date.now(),victory:false});
const atRegionEnd=await ev("JSON.parse(localStorage.getItem('eternalSlayerSave'))");await ev("document.querySelector('[data-act=sweep]').click()");const regionAdvance=await ev("JSON.parse(localStorage.getItem('eternalSlayerSave'))");
await load({stage:20,region:9,kills:100,stageKills:0,boss:true,enemyHp:1,atk:1000000,auto:false,lastSeen:Date.now(),victory:false});
await ev("document.querySelector('[data-act=sweep]').click()");const finalBoss=await ev("({save:JSON.parse(localStorage.getItem('eternalSlayerSave')),banner:document.querySelector('#content-panel').textContent,enemy:document.querySelector('#enemy-name').textContent,attack:!!document.querySelector('[data-act=sweep]')})");await ev("document.querySelector('#advance-btn').click()");const afterVictory=await ev("JSON.parse(localStorage.getItem('eternalSlayerSave'))");
const mobile=[];for(const width of [320,360,390,430]){await call('Emulation.setDeviceMetricsOverride',{width,height:844,deviceScaleFactor:1,mobile:true});await wait(100);mobile.push(await ev("({width:innerWidth,docWidth:document.documentElement.scrollWidth,bodyWidth:document.body.scrollWidth,shell:document.querySelector('.game-shell').getBoundingClientRect().width,content:document.querySelector('#content-panel').getBoundingClientRect().width})"))}
console.log(JSON.stringify({stage5Before:{stage:stage5Before.stage,boss:stage5Before.boss},boss:{stage:boss.stage,boss:boss.boss,cleared:boss.cleared},atRegionEnd:{region:atRegionEnd.region,stage:atRegionEnd.stage,boss:atRegionEnd.boss},regionAdvance:{region:regionAdvance.region,stage:regionAdvance.stage,cleared:regionAdvance.cleared},finalBoss:{region:finalBoss.save.region,stage:finalBoss.save.stage,victory:finalBoss.save.victory,boss:finalBoss.save.boss,enemy:finalBoss.enemy,banner:finalBoss.banner.includes('ETERNAL CITADEL CLEARED'),attack:finalBoss.attack},afterVictory:{region:afterVictory.region,stage:afterVictory.stage,victory:afterVictory.victory},mobile,errors},null,2));
ws.close();proc.kill();

